local activePage = "home"
local selectPage
do
    local pageObjects = { home = dashboard, main = mainContent, aim = content, world = worldContent, map = win:FindFirstChild("MapContent"), farm = win:FindFirstChild("FarmContent"), visual = visualContent, emotes = emotesContent, misc = miscContent }
    pcall(function()
        getgenv().__NoirRegisterPage = function(name, object)
            if type(name) == "string" and typeof(object) == "Instance" then pageObjects[name] = object end
        end
    end)
    local pageBasePosition = content.Position
    local pageTransitionId = 0
    local function pageScaleFor(object)
        local scaler = object:FindFirstChild("NoirPageScale")
        if not scaler then scaler = New("UIScale", { Name = "NoirPageScale", Scale = 1, Parent = object }) end
        return scaler
    end
    function selectPage(page)
        if not pageObjects[page] then page = "home" end
        pageTransitionId += 1
        local transitionId = pageTransitionId
        local oldPage = activePage
        local oldObject = pageObjects[oldPage]
        local newObject = pageObjects[page]
        activePage = page

        for _, object in pairs(pageObjects) do
            if object ~= oldObject and object ~= newObject then
                object.Visible = false
                object.Position = pageBasePosition
                pageScaleFor(object).Scale = 1
            end
        end
        if oldObject and oldObject ~= newObject and oldObject.Visible then
            local oldScale = pageScaleFor(oldObject)
            oldObject.Position = pageBasePosition
            TweenService:Create(oldScale, TweenInfo.new(.14, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Scale = .98 }):Play()
            task.delay(.14, function()
                if transitionId == pageTransitionId and oldObject ~= pageObjects[activePage] then
                    oldObject.Visible = false
                    oldObject.Position = pageBasePosition
                    oldScale.Scale = 1
                end
            end)
        end
        if newObject then
            local newScale = pageScaleFor(newObject)
            newObject.Position = pageBasePosition
            if newObject:IsA("ScrollingFrame") then
                newObject.CanvasPosition = Vector2.new(0, newObject.CanvasPosition.Y)
            end
            newScale.Scale = .975
            newObject.Visible = true
            TweenService:Create(newScale, TweenInfo.new(.30, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Scale = 1 }):Play()
        end
        configContent.Visible = false
        __NOIR_GUARD.navState.active = page
        for name, b in pairs(navButtons) do
            local active = name == page
            TweenService:Create(b, TweenInfo.new(.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { BackgroundColor3 = active and C.card or C.surface, BackgroundTransparency = active and .16 or 1 }):Play()
            local data = navIcons[name]
            if data then
                if data.stroke then TweenService:Create(data.stroke, TweenInfo.new(.2), { Color = active and C.accent2 or C.border, Transparency = active and .66 or .88 }):Play() end
                TweenService:Create(data.icon, TweenInfo.new(.2), { ImageColor3 = active and C.accent or C.dim }):Play()
                if data.glyphs then
                    for _, glyph in ipairs(data.glyphs) do TweenService:Create(glyph, TweenInfo.new(.2), { BackgroundColor3 = active and C.accent or C.dim }):Play() end
                end
                if data.rings then
                    for _, ring in ipairs(data.rings) do TweenService:Create(ring, TweenInfo.new(.2), { Color = active and C.accent or C.dim }):Play() end
                end
                TweenService:Create(data.label, TweenInfo.new(.2), { TextColor3 = active and C.text or C.dim }):Play()
                TweenService:Create(data.bar, TweenInfo.new(.2), { BackgroundTransparency = active and .16 or 1 }):Play()
                if data.barTween then pcall(function() data.barTween:Cancel() end) data.barTween = nil end
                if data.glowTween then pcall(function() data.glowTween:Cancel() end) data.glowTween = nil end
                if active then
                    if not data.barStroke then
                        data.barStroke = New("UIStroke", { Parent = data.bar, Color = Color3.fromRGB(255,255,255), Thickness = 2, Transparency = .55 })
                    end
                    data.barTween = TweenService:Create(data.barStroke, TweenInfo.new(1.2, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Transparency = .08 })
                    data.barTween:Play()
                    if data.stroke then
                        data.glowTween = TweenService:Create(data.stroke, TweenInfo.new(1.9, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Transparency = .52 })
                        data.glowTween:Play()
                    end
                end
            end
        end
    end
end
for name, b in pairs(navButtons) do b.MouseButton1Click:Connect(function() if activePage == name then selectPage("home") else selectPage(name) end end) end
selectPage("home")

local sectionCount, mainSectionCount, worldSectionCount, visualSectionCount, emotesSectionCount, miscSectionCount, configSectionCount = 0, 0, 0, 0, 0, 0, 0
local sectionPanels, controls = {}, {}
function refreshCanvas()
     
     
    task.defer(function()
        for _, page in ipairs({ content, configContent, visualContent, mainContent, worldContent, emotesContent, miscContent }) do
            if page and page.Parent then page.CanvasSize = UDim2.fromOffset(0, 0) end
        end
    end)
end
search:GetPropertyChangedSignal("Text"):Connect(function()
    local q = string.lower(search.Text or "")
    local counts = { main = 0, aim = 0, world = 0, visual = 0, emotes = 0, misc = 0, map = 0, farm = 0 }
    local firstPage, firstSub
    for _, entry in ipairs(sectionPanels) do
        local hay = entry.name
        for _, d in ipairs(entry.panel:GetDescendants()) do
            if d:IsA("TextLabel") or d:IsA("TextButton") then hay = hay .. " " .. string.lower(d.Text or "") end
        end
        local match = q == "" or string.find(hay, q, 1, true) ~= nil
        entry.panel.Visible = match
        if match then
            counts[entry.page] = (counts[entry.page] or 0) + 1
            if q ~= "" and not firstPage then
                firstPage, firstSub = entry.page, entry.sub
            end
        end
    end
    if q ~= "" and firstPage then
        if activePage == "home" or activePage == "skins" or activePage ~= firstPage then
            selectPage(firstPage)
        end
        local shower = getgenv().__NoirSubShow and getgenv().__NoirSubShow[firstPage]
        if type(shower) == "function" and firstSub then pcall(shower, firstSub) end
    elseif q == "" then
        local cur = getgenv().__NoirSubCurrent and getgenv().__NoirSubCurrent[activePage]
        local shower = getgenv().__NoirSubShow and getgenv().__NoirSubShow[activePage]
        if type(shower) == "function" and cur then pcall(shower, cur) end
    end
    refreshCanvas()
end)

local host = {}

local notificationHolder = New("Frame", {
    Parent = gui, Name = "NotificationRail", AnchorPoint = Vector2.new(1, 0),
    Position = UDim2.new(1, -20, 0, 82), Size = UDim2.new(0, 360, 0, 270),
    BackgroundTransparency = 1, ClipsDescendants = false, ZIndex = 1000,
})
local notificationLayout = New("UIListLayout", {
    Parent = notificationHolder, Padding = UDim.new(0, 9),
    FillDirection = Enum.FillDirection.Vertical, HorizontalAlignment = Enum.HorizontalAlignment.Right,
    VerticalAlignment = Enum.VerticalAlignment.Top, SortOrder = Enum.SortOrder.LayoutOrder,
})
local notificationSerial = 0
local activeNotifications = {}
local function trimNotifications()
    while #activeNotifications > 3 do
        local oldest = table.remove(activeNotifications, 1)
        if oldest and oldest.Parent then oldest:Destroy() end
    end
end
function host.Notify(title, duration)
    notificationSerial += 1
    local life = math.max(1.5, tonumber(duration) or 3)
    local card = New("Frame", {
        Parent = notificationHolder, Name = "Toast_" .. tostring(notificationSerial),
        Size = UDim2.new(1, 0, 0, 88), BackgroundColor3 = C.panel,
        BackgroundTransparency = 1, BorderSizePixel = 0, LayoutOrder = notificationSerial,
        ClipsDescendants = false, ZIndex = 1000,
    })
    corner(card, 10)
    stroke(card, C.accent, .34)
    New("UIGradient", { Parent = card, Color = ColorSequence.new({
        ColorSequenceKeypoint.new(0, Color3.fromRGB(20,22,27)),
        ColorSequenceKeypoint.new(1, Color3.fromRGB(7,8,11)),
    }), Rotation = 15 })
    New("Frame", { Parent = card, Position = UDim2.fromOffset(0, 12), Size = UDim2.fromOffset(2, 62),
        BackgroundColor3 = C.accent, BorderSizePixel = 0, ZIndex = 1001 })
    __NOIR_GUARD.blackhole.Create(card, UDim2.fromOffset(13, 25), 38, Vector2.zero, 1002, 19)
    local badge = New("TextLabel", { Parent = card, Position = UDim2.fromOffset(61, 10), Size = UDim2.new(1, -122, 0, 17),
        BackgroundTransparency = 1, Text = "NOIR  //  EVENT LOG", TextColor3 = C.accent2,
        TextSize = 9, Font = Enum.Font.GothamBold, TextXAlignment = Enum.TextXAlignment.Left,
        TextTransparency = 1, ZIndex = 1003 })
    local stampText = "SYSTEM"
    pcall(function() stampText = os.date("%H:%M:%S") end)
    local stamp = New("TextLabel", { Parent = card, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, -13, 0, 10), Size = UDim2.fromOffset(62, 16),
        BackgroundTransparency = 1, Text = stampText, TextColor3 = C.dim,
        TextSize = 8, Font = Enum.Font.Code, TextXAlignment = Enum.TextXAlignment.Right,
        TextTransparency = 1, ZIndex = 1003 })
    local message = New("TextLabel", { Parent = card, Position = UDim2.fromOffset(61, 31), Size = UDim2.new(1, -76, 0, 40),
        BackgroundTransparency = 1, Text = tostring(title), TextColor3 = C.text,
        TextSize = 13, Font = Enum.Font.Gotham, TextWrapped = true, TextTruncate = Enum.TextTruncate.AtEnd,
        TextXAlignment = Enum.TextXAlignment.Left, TextYAlignment = Enum.TextYAlignment.Center,
        TextTransparency = 1, ZIndex = 1003 })
    local progress = New("Frame", { Parent = card, Position = UDim2.fromOffset(61, 77), Size = UDim2.new(1, -76, 0, 2),
        BackgroundColor3 = C.accent, BorderSizePixel = 0, ZIndex = 1003 })
    local scaleIn = New("UIScale", { Parent = card, Scale = .92 })
    table.insert(activeNotifications, card); trimNotifications()
    TweenService:Create(card, TweenInfo.new(.24, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), { BackgroundTransparency = .08 }):Play()
    TweenService:Create(scaleIn, TweenInfo.new(.24, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Scale = 1 }):Play()
    TweenService:Create(badge, TweenInfo.new(.22), { TextTransparency = 0 }):Play()
    TweenService:Create(stamp, TweenInfo.new(.22), { TextTransparency = 0 }):Play()
    TweenService:Create(message, TweenInfo.new(.26), { TextTransparency = 0 }):Play()
    TweenService:Create(progress, TweenInfo.new(life, Enum.EasingStyle.Linear), { Size = UDim2.new(0, 0, 0, 2) }):Play()
    task.delay(life, function()
        for i = #activeNotifications, 1, -1 do
            if activeNotifications[i] == card then table.remove(activeNotifications, i) break end
        end
        if card.Parent then
            TweenService:Create(card, TweenInfo.new(.22, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { BackgroundTransparency = 1 }):Play()
            TweenService:Create(scaleIn, TweenInfo.new(.24, Enum.EasingStyle.Quad, Enum.EasingDirection.In), { Scale = .94 }):Play()
            TweenService:Create(badge, TweenInfo.new(.16), { TextTransparency = 1 }):Play()
            TweenService:Create(stamp, TweenInfo.new(.16), { TextTransparency = 1 }):Play()
            TweenService:Create(message, TweenInfo.new(.16), { TextTransparency = 1 }):Play()
            task.delay(.25, function() if card.Parent then card:Destroy() end end)
        end
    end)
end
function host.CreateTab()
    local tab = {}
    function tab:AddSection(name, description)
        local isVisual = name == "Visuals" or name == "Object ESP" or string.find(name, "VISUAL", 1, true) == 1
        local isMain = string.sub(name, 1, 5) == "MAIN "
        local function hasTag(p) return string.find(name, p, 1, true) ~= nil end
        local isFling = hasTag("Fling") or hasTag("⚡") or hasTag("🤖") or hasTag("📋") or hasTag("⚙") or hasTag("🔘") or hasTag("🔑")
        local isWorld = string.sub(name, 1, 6) == "WORLD " or name == "Bomb Jump+" or name == "Gold Bomb Jump+" or isFling
        local isEmotes = string.sub(name, 1, 7) == "EMOTES " or name == "FE Animations" or name == "About"
        local isMisc = string.sub(name, 1, 5) == "MISC " or name == "Inventory Unlimiter V5" or name == "Pm-WallHop"
        local col, page = nil, "aim"
        if isVisual then visualSectionCount += 1; col = visualCols[(visualSectionCount - 1) % 2 + 1]; page = "visual"
        elseif isMain then mainSectionCount += 1; col = mainCols[(mainSectionCount - 1) % 2 + 1]; page = "main"
        elseif isWorld then worldSectionCount += 1; col = worldCols[(worldSectionCount - 1) % 2 + 1]; page = "world"
        elseif isEmotes then emotesSectionCount += 1; col = emotesCols[(emotesSectionCount - 1) % 2 + 1]; page = "emotes"
        elseif isMisc then miscSectionCount += 1; col = miscCols[(miscSectionCount - 1) % 2 + 1]; page = "misc"
        else sectionCount += 1; col = cols[(sectionCount - 1) % 2 + 1] end
        local panel = New("Frame", { Parent = col, Size = UDim2.new(1, 0, 0, 90), AutomaticSize = Enum.AutomaticSize.Y,
            BackgroundColor3 = C.panel, BackgroundTransparency = .36, ClipsDescendants = true })
        corner(panel, 18)
        local panelEdge = stroke(panel, C.border, .5)
        local panelSheen = New("Frame", { Parent = panel, Name = "CardSheen", Position = UDim2.fromScale(-.6, -.25),
            Size = UDim2.new(.5, 1.5), Rotation = 14, BackgroundColor3 = Color3.fromRGB(255,255,255),
            BackgroundTransparency = .94, BorderSizePixel = 0, ZIndex = 0 })
        panel.MouseEnter:Connect(function()
            TweenService:Create(panel, TweenInfo.new(.24, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { BackgroundTransparency = .28 }):Play()
            TweenService:Create(panelEdge, TweenInfo.new(.24), { Transparency = .32 }):Play()
            panelSheen.Position = UDim2.fromScale(-.6, -.25)
            TweenService:Create(panelSheen, TweenInfo.new(.75, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Position = UDim2.fromScale(1.25, -.25) }):Play()
        end)
        panel.MouseLeave:Connect(function()
            TweenService:Create(panel, TweenInfo.new(.26, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { BackgroundTransparency = .36 }):Play()
            TweenService:Create(panelEdge, TweenInfo.new(.26), { Transparency = .5 }):Play()
        end)
        local tick = New("Frame", { Parent = panel, Position = UDim2.fromOffset(0, 16), Size = UDim2.fromOffset(3, 20), BackgroundColor3 = C.accent })
        corner(tick, 2)
        table.insert(sectionPanels, { panel = panel, page = page, name = string.lower(name .. " " .. (description or "")) })
        local shownName = name:gsub("^MAIN • ", ""):gsub("^WORLD • ", ""):gsub("^VISUAL • ", ""):gsub("^EMOTES • ", ""):gsub("^MISC • ", "")
        text(panel, shownName, 18, UDim2.fromOffset(24, 16))
        if description and description ~= "" then text(panel, description, 12, UDim2.fromOffset(24, 44), true) end
        local holder = New("Frame", { Parent = panel, Position = UDim2.fromOffset(20, description ~= "" and 74 or 57), Size = UDim2.new(1, -40, 0, 0),
            AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1 })
        New("UIListLayout", { Parent = holder, Padding = UDim.new(0, 3), SortOrder = Enum.SortOrder.LayoutOrder })
        New("UIPadding", { Parent = holder, PaddingBottom = UDim.new(0, 12) })
        holder:GetPropertyChangedSignal("AbsoluteSize"):Connect(refreshCanvas); refreshCanvas()
        local api = { Name = name }
        local storagePrefix = name .. "::"
        local function row(label, h)
            local r = New("Frame", { Parent = holder, Size = UDim2.new(1, 0, 0, h or 62), BackgroundTransparency = 1 })
            text(r, label, 16, UDim2.fromOffset(0, 10))
            return r
        end
        function api:AddToggle(label, callback)
            local savedToggle = NoirPersistence.data.toggles[storagePrefix .. label]
            if savedToggle == nil and NoirPersistence.safeLegacy[label] then
                savedToggle = NoirPersistence.data.toggles[label]
                if savedToggle ~= nil then NoirPersistence.data.toggles[storagePrefix .. label] = savedToggle; NoirPersistence.Save() end
            end
            local state = savedToggle == true
            local r = row(label, 52)
            local pill = New("TextButton", { Parent = r, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 8), Size = UDim2.fromOffset(64, 34),
                BackgroundColor3 = Color3.fromRGB(7,8,11), BackgroundTransparency = .32, BorderSizePixel = 0, Text = "", AutoButtonColor = false })
            corner(pill, 17)
            local pillStroke = stroke(pill, C.border, .30); pillStroke.Thickness = 1.35
            local pillScale = New("UIScale", { Parent = pill, Scale = 1 })
            pill.MouseEnter:Connect(function()
                TweenService:Create(pillScale, TweenInfo.new(.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Scale = 1.07 }):Play()
            end)
            pill.MouseLeave:Connect(function()
                TweenService:Create(pillScale, TweenInfo.new(.2, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Scale = 1 }):Play()
            end)
            local dot = New("Frame", { Parent = pill, Position = UDim2.fromOffset(4, 4), Size = UDim2.fromOffset(26, 26), BackgroundColor3 = Color3.fromRGB(150,155,162) })
            corner(dot, 13)
            local switchGlow = nil
            local function set(v, persist)
                state = v == true
                TweenService:Create(pill, TweenInfo.new(.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                    BackgroundColor3 = state and Color3.fromRGB(22,24,29) or Color3.fromRGB(7,8,11),
                    BackgroundTransparency = state and .18 or .32,
                }):Play()
                TweenService:Create(pillStroke, TweenInfo.new(.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                    Color = state and C.accent2 or C.border, Transparency = state and .05 or .30,
                }):Play()
                TweenService:Create(dot, TweenInfo.new(.24, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Position = state and UDim2.fromOffset(34, 4) or UDim2.fromOffset(4, 4), BackgroundColor3 = state and C.accent2 or Color3.fromRGB(150,155,162), Size = UDim2.fromOffset(30, 30) }):Play()
                task.delay(.20, function() if dot.Parent then TweenService:Create(dot, TweenInfo.new(.16, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Size = UDim2.fromOffset(26, 26) }):Play() end end)
                if state then
                    if not switchGlow then
                        switchGlow = TweenService:Create(pillStroke, TweenInfo.new(1.4, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut, -1, true), { Transparency = .34 })
                        switchGlow:Play()
                    end
                elseif switchGlow then
                    switchGlow:Cancel(); switchGlow = nil
                end
                callback(state)
                if persist ~= false then NoirPersistence.data.toggles[storagePrefix .. label] = state; NoirPersistence.Save() end
            end
            local lastClick = 0
            local function toggleClick()
                local now = os.clock()
                if now - lastClick < .18 then return end
                lastClick = now
                set(not state, true)
            end
            pill.MouseButton1Click:Connect(toggleClick)
            pill.Activated:Connect(toggleClick)
            set(state, false)
            return function(v) set(v == nil and not state or v, true) end
        end
        function api:AddButton(label, callback)
            local b = New("TextButton", { Parent = holder, Size = UDim2.new(1, 0, 0, 46), BackgroundColor3 = C.btn,
                BackgroundTransparency = .32, BorderSizePixel = 0, Text = label, TextColor3 = C.text, TextSize = 15,
                Font = Enum.Font.GothamMedium, AutoButtonColor = false })
            corner(b, 11)
            local edge = stroke(b, C.border, .24); edge.Thickness = 1.35
            local press = New("UIScale", { Parent = b, Scale = 1 })
            b.ClipsDescendants = true
            local shine = New("Frame", { Parent = b, Name = "HoverShine", Position = UDim2.fromScale(-.65, -.2),
                Size = UDim2.new(.42, 1.5), Rotation = 16, BackgroundColor3 = Color3.fromRGB(255,255,255),
                BackgroundTransparency = .88, BorderSizePixel = 0, ZIndex = 1 })
            b.MouseEnter:Connect(function()
                TweenService:Create(b, TweenInfo.new(.18), { BackgroundColor3 = Color3.fromRGB(22,24,29), BackgroundTransparency = .18 }):Play()
                TweenService:Create(edge, TweenInfo.new(.18), { Transparency = .05 }):Play()
                shine.Position = UDim2.fromScale(-.65, -.2)
                TweenService:Create(shine, TweenInfo.new(.65, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Position = UDim2.fromScale(1.25, -.2) }):Play()
            end)
            b.MouseLeave:Connect(function()
                TweenService:Create(b, TweenInfo.new(.20), { BackgroundColor3 = C.btn, BackgroundTransparency = .32 }):Play()
                TweenService:Create(edge, TweenInfo.new(.20), { Transparency = .24 }):Play()
                TweenService:Create(press, TweenInfo.new(.18, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Scale = 1 }):Play()
            end)
            b.MouseButton1Down:Connect(function() TweenService:Create(press, TweenInfo.new(.10, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Scale = .975 }):Play() end)
            b.MouseButton1Up:Connect(function() TweenService:Create(press, TweenInfo.new(.18, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), { Scale = 1 }):Play() end)
            local lastClick = 0
            local function fire()
                local now = os.clock()
                if now - lastClick < .18 then return end
                lastClick = now
                callback()
            end
            b.MouseButton1Click:Connect(fire)
            b.Activated:Connect(fire)
            return b
        end
        function api:AddSlider(label, min, max, default, callback)
            local savedSlider = NoirPersistence.data.sliders[storagePrefix .. label]
            if savedSlider == nil then
                savedSlider = NoirPersistence.data.sliders[label]
                if savedSlider ~= nil then NoirPersistence.data.sliders[storagePrefix .. label] = savedSlider; NoirPersistence.Save() end
            end
            default = tonumber(savedSlider) or default
            local r = row(label, 68)
            local value = New("TextBox", { Parent = r, Position = UDim2.new(1, -72, 0, 5), Size = UDim2.fromOffset(72, 30), BackgroundColor3 = C.surface,
                BackgroundTransparency = .30, Text = tostring(default), TextColor3 = C.text, TextSize = 14, Font = Enum.Font.Gotham,
                TextXAlignment = Enum.TextXAlignment.Center, ClearTextOnFocus = false })
            corner(value, 9); stroke(value, C.border, .4)
            local track = New("Frame", { Parent = r, Position = UDim2.new(0, 0, 1, -18), Size = UDim2.new(1, 0, 0, 6), BackgroundColor3 = C.off })
            corner(track, 3)
            local fill = New("Frame", { Parent = track, Size = UDim2.fromScale((default - min) / (max - min), 1), BackgroundColor3 = C.accent })
            corner(fill, 3)
            local knob = New("Frame", { Parent = track, AnchorPoint = Vector2.new(.5, .5), Position = UDim2.new((default - min) / (max - min), 0, .5, 0), Size = UDim2.fromOffset(14, 14), BackgroundColor3 = C.text })
            corner(knob, 7); stroke(knob, C.border, .3)
            local current = default
            local function set(v, persist)
                current = math.clamp(math.floor((tonumber(v) or current or default) + .5), min, max)
                fill.Size = UDim2.fromScale((current - min) / (max - min), 1)
                knob.Position = UDim2.new((current - min) / (max - min), 0, .5, 0)
                value.Text = tostring(current)
                callback(current)
                if persist ~= false then NoirPersistence.data.sliders[storagePrefix .. label] = current; NoirPersistence.Save() end
            end
            set(default, false)
            value.FocusLost:Connect(function() set(value.Text) end)
            local drag = false
            track.InputBegan:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then
                    drag = true; set(min + (max - min) * math.clamp((i.Position.X - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1))
                end
            end)
            UIS.InputChanged:Connect(function(i)
                if drag and (i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseMovement) then
                    set(min + (max - min) * math.clamp((i.Position.X - track.AbsolutePosition.X) / track.AbsoluteSize.X, 0, 1))
                end
            end)
            UIS.InputEnded:Connect(function(i)
                if i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseButton1 then drag = false end
            end)
            return { SetValue = function(_, v) set(v) end, GetValue = function() return current end }
        end
        function api:AddDropdown(label, values, callback)
            local r = row(label, 56)
