        end)
        makeBtn(tpHolder, "Teleport to Sheriff", function()
            local target = currentSheriff()
            if not target then notify("Sheriff не найден", 3); return end
            tpToPlayer(target)
        end)

        local listHolder = panel("Players", "Как в Fling → Lists")
        local roleLabel = New("TextLabel", { Parent = listHolder, Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1,
            Text = "Murder: —  ·  Sheriff: —", TextColor3 = C.dim, TextSize = 13, Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left })
        local function refreshRoles()
            local m, s = currentMurder(), currentSheriff()
            roleLabel.Text = "Murder: " .. (m and m.Name or "—") .. "  ·  Sheriff: " .. (s and s.Name or "—")
        end
        local ddRow = New("Frame", { Parent = listHolder, Size = UDim2.new(1, 0, 0, 56), BackgroundTransparency = 1 })
        text(ddRow, "▸ Player", 16, UDim2.fromOffset(0, 10))
        local ddBtn = New("TextButton", { Parent = ddRow, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 4), Size = UDim2.fromOffset(190, 42),
            BackgroundColor3 = Color3.fromRGB(7,8,11), BackgroundTransparency = .30, BorderSizePixel = 0,
            Text = "None  ⌄", TextColor3 = C.text, TextSize = 14, Font = Enum.Font.Gotham, AutoButtonColor = false, ZIndex = 5 })
        corner(ddBtn, 10)
        local playerDropEdge = stroke(ddBtn, C.border, .24); playerDropEdge.Thickness = 1.25
        ddBtn.MouseEnter:Connect(function()
            TweenService:Create(ddBtn, TweenInfo.new(.16), { BackgroundColor3 = Color3.fromRGB(22,24,29), BackgroundTransparency = .18 }):Play()
            TweenService:Create(playerDropEdge, TweenInfo.new(.16), { Transparency = .05 }):Play()
        end)
        ddBtn.MouseLeave:Connect(function()
            TweenService:Create(ddBtn, TweenInfo.new(.18), { BackgroundColor3 = Color3.fromRGB(7,8,11), BackgroundTransparency = .30 }):Play()
            TweenService:Create(playerDropEdge, TweenInfo.new(.18), { Transparency = .24 }):Play()
        end)
        local popup
        local function closePopup() if popup then popup:Destroy(); popup = nil end end
        local function playerNames()
            local names = { "None" }
            for _, player in ipairs(getPlayers()) do
                if player ~= LocalPlayer then names[#names + 1] = player.Name end
            end
            table.sort(names, function(a, b)
                if a == "None" then return true end
                if b == "None" then return false end
                return string.lower(a) < string.lower(b)
            end)
            return names
        end
        local function openPopup()
            closePopup()
            refreshRoles()
            local names = playerNames()
            local scaleVal = (scale and scale.Scale) or 1
            popup = New("ScrollingFrame", { Parent = gui, Position = UDim2.fromOffset(ddBtn.AbsolutePosition.X / scaleVal, (ddBtn.AbsolutePosition.Y + ddBtn.AbsoluteSize.Y + 4) / scaleVal),
                Size = UDim2.fromOffset(ddBtn.AbsoluteSize.X / scaleVal, math.min(#names * 38, 190)), CanvasSize = UDim2.fromOffset(0, #names * 38),
                BackgroundColor3 = C.surface, BorderSizePixel = 0, ScrollBarThickness = 4, ZIndex = 50 })
            corner(popup, 10); stroke(popup, C.accent, .2)
            New("UIListLayout", { Parent = popup, SortOrder = Enum.SortOrder.LayoutOrder })
            for _, name in ipairs(names) do
                local item = New("TextButton", { Parent = popup, Size = UDim2.new(1, 0, 0, 38), BackgroundColor3 = Color3.fromRGB(7,8,11),
                    BackgroundTransparency = .32, BorderSizePixel = 0, Text = tostring(name), TextColor3 = C.text,
                    TextSize = 14, Font = Enum.Font.Gotham, ZIndex = 51, AutoButtonColor = false })
                corner(item, 8)
                local itemEdge = stroke(item, C.border, .66); itemEdge.Thickness = 1
                item.MouseEnter:Connect(function()
                    TweenService:Create(item, TweenInfo.new(.12), { BackgroundColor3 = Color3.fromRGB(22,24,29), BackgroundTransparency = .18 }):Play()
                    TweenService:Create(itemEdge, TweenInfo.new(.12), { Transparency = .16 }):Play()
                end)
                item.MouseLeave:Connect(function()
                    TweenService:Create(item, TweenInfo.new(.14), { BackgroundColor3 = Color3.fromRGB(7,8,11), BackgroundTransparency = .32 }):Play()
                    TweenService:Create(itemEdge, TweenInfo.new(.14), { Transparency = .66 }):Play()
                end)
                local function pick()
                    ddBtn.Text = tostring(name) .. "  ⌄"
                    closePopup()
                    if name == "None" then return end
                    local player = Players:FindFirstChild(name)
                    if player then tpToPlayer(player) end
                end
                item.MouseButton1Click:Connect(pick)
                item.Activated:Connect(pick)
            end
        end
        ddBtn.MouseButton1Click:Connect(openPopup)
        ddBtn.Activated:Connect(openPopup)
        local bus = getgenv().__NoirV4RoleBus
        if bus and bus.Subscribe then bus:Subscribe(function() task.defer(refreshRoles) end) end
        refreshRoles()
    end
end

do
    local function buildAutofarmUI()
        local page = win:FindFirstChild("FarmContent")
        local col = page and page:FindFirstChild("NoirColumn1")
        if page and col then
            local function panel(title, subtitle)
                local card = New("Frame", { Parent = col, Size = UDim2.new(1, 0, 0, 90), AutomaticSize = Enum.AutomaticSize.Y,
                    BackgroundColor3 = C.panel, BackgroundTransparency = .36, ClipsDescendants = true })
                table.insert(sectionPanels, { panel = card, page = "farm", name = string.lower(title .. " " .. (subtitle or "") .. " autofarm farm coins coin") })
                corner(card, 18); stroke(card, C.border, .5)
                local tick = New("Frame", { Parent = card, Position = UDim2.fromOffset(0, 16), Size = UDim2.fromOffset(3, 20), BackgroundColor3 = C.accent })
                corner(tick, 2)
                text(card, title, 18, UDim2.fromOffset(24, 16))
                if subtitle and subtitle ~= "" then text(card, subtitle, 12, UDim2.fromOffset(24, 44), true) end
                local holder = New("Frame", { Parent = card, Position = UDim2.fromOffset(20, subtitle ~= "" and 74 or 57), Size = UDim2.new(1, -40, 0, 0),
                    AutomaticSize = Enum.AutomaticSize.Y, BackgroundTransparency = 1 })
                New("UIListLayout", { Parent = holder, Padding = UDim.new(0, 6), SortOrder = Enum.SortOrder.LayoutOrder })
                New("UIPadding", { Parent = holder, PaddingBottom = UDim.new(0, 12) })
                return holder
            end
            local function makeToggle(parent, label, callback, startOn)
                local state = false
                local r = New("Frame", { Parent = parent, Size = UDim2.new(1, 0, 0, 52), BackgroundTransparency = 1 })
                text(r, label, 16, UDim2.fromOffset(0, 10))
                local pill = New("TextButton", { Parent = r, AnchorPoint = Vector2.new(1, 0), Position = UDim2.new(1, 0, 0, 8), Size = UDim2.fromOffset(64, 34),
                    BackgroundColor3 = Color3.fromRGB(7,8,11), BackgroundTransparency = .32, BorderSizePixel = 0, Text = "", AutoButtonColor = false })
                corner(pill, 17)
                local pillEdge = stroke(pill, C.border, .30); pillEdge.Thickness = 1.35
                local dot = New("Frame", { Parent = pill, Position = UDim2.fromOffset(4, 4), Size = UDim2.fromOffset(26, 26), BackgroundColor3 = Color3.fromRGB(150, 155, 162) })
                corner(dot, 13)
                local function apply(v)
                    state = v == true
                    TweenService:Create(pill, TweenInfo.new(.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                        BackgroundColor3 = state and Color3.fromRGB(22,24,29) or Color3.fromRGB(7,8,11),
                        BackgroundTransparency = state and .18 or .32,
                    }):Play()
                    TweenService:Create(pillEdge, TweenInfo.new(.22, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                        Color = state and C.accent2 or C.border, Transparency = state and .05 or .30,
                    }):Play()
                    TweenService:Create(dot, TweenInfo.new(.32, Enum.EasingStyle.Quart, Enum.EasingDirection.Out), {
                        Position = state and UDim2.fromOffset(34, 4) or UDim2.fromOffset(4, 4),
                        BackgroundColor3 = state and C.accent2 or Color3.fromRGB(150, 155, 162)
                    }):Play()
                    callback(state)
                end
                local last = 0
                local function fire()
                    local now = os.clock()
                    if now - last < .18 then return end
                    last = now
                    apply(not state)
                end
                pill.MouseButton1Click:Connect(fire)
                pill.Activated:Connect(fire)
                if startOn == true then apply(true) end
            end
            local farming, gunFarm, auraOn, resetFull, killAllOn, shootMurdOn, noRenderOn = false, false, false, false, false, false, false
            local bagIsFull, auraRadius = false, 8
            local noclipConn, auraConn, statusLbl
            local fopt = { method = "Standard", spd = 30, dly = 10, avoid = false, rstM = false, rstS = false, ret = "Map" }
            local lastMapCF, lastCoin, holdReturnUntil, farmTw = nil, nil, 0, nil
            local function farmKey(k) return "Autofarm::" .. k end
            local function farmRead(bag, key, def)
                local store = NoirPersistence.data[bag]
                if type(store) ~= "table" then return def end
                local v = store[farmKey(key)]
                if v == nil then return def end
                return v
            end
            local function farmWrite(bag, key, val)
                NoirPersistence.data[bag][farmKey(key)] = val
                NoirPersistence.Save()
            end
            fopt.spd = math.clamp(tonumber(farmRead("sliders", "Tween Speed (%)", 30)) or 30, 1, 100)
            fopt.dly = math.clamp(tonumber(farmRead("sliders", "Tween Delay (%)", 10)) or 10, 0, 100)
            fopt.method = farmRead("dropdowns", "Method", "Standard")
            if fopt.method ~= "Lay" then fopt.method = "Standard" end
            fopt.ret = farmRead("dropdowns", "Return To", "Map")
            if fopt.ret ~= "Above Map" and fopt.ret ~= "Lobby" then fopt.ret = "Map" end
            fopt.avoid = farmRead("toggles", "Farm Avoid Murderer", false) == true
            fopt.rstM = farmRead("toggles", "Auto Reset As Murderer", false) == true
            fopt.rstS = farmRead("toggles", "Auto Reset As Sheriff", false) == true
            auraRadius = tonumber(farmRead("sliders", "Aura radius", 8)) or 8
            local origDestroyH = workspace.FallenPartsDestroyHeight
            local function setStatus(msg)
                if statusLbl then statusLbl.Text = msg end
            end
            local function touch(a, b)
                pcall(function()
                    firetouchinterest(a, b, 0)
                    firetouchinterest(a, b, 1)
                end)
            end
            local function getContainer()
                for _, child in ipairs(workspace:GetChildren()) do
                    if child:IsA("Model") then
                        local inner = child:FindFirstChild("CoinContainer")
                        if inner then return inner, child end
                    end
                end
                local box = workspace:FindFirstChild("CoinContainer")
                if box then return box, box.Parent end
                return nil, nil
            end
            local function getCoinParts()
                local parts, box = {}, getContainer()
                if not box then return parts end
                for _, child in ipairs(box:GetChildren()) do
                    if child.Name == "Coin_Server" or child.Name == "CoinVisual" or child.Name == "Coin" or child.Name == "Candy" or child:FindFirstChild("TouchInterest") then
                        if child:IsA("BasePart") then
                            parts[#parts + 1] = child
                        else
                            local p = child:FindFirstChildWhichIsA("BasePart", true)
                            if p then parts[#parts + 1] = p end
                        end
                    end
                end
                if #parts == 0 then
                    local ok, descs = pcall(function() return box:GetDescendants() end)
                    if ok and descs then
                        for n = 1, #descs do
                            local d = descs[n]
                            if d:IsA("BasePart") and d:FindFirstChild("TouchInterest") then
                                parts[#parts + 1] = d
                            end
                        end
                    end
                end
                return parts
            end
            local function poseAt(part)
                local pos = part.Position
                if fopt.method == "Lay" then
                     
                    return CFrame.new(pos.X, pos.Y - 2, pos.Z) * CFrame.Angles(math.pi / 2, 0, 0)
                end
                 
                return CFrame.new(pos.X, pos.Y + 2.4, pos.Z)
            end
            local function freezeRoot(r, on)
                if not r then return end
                pcall(function()
                    r.Anchored = on and true or false
                    r.AssemblyLinearVelocity = Vector3.zero
                    r.AssemblyAngularVelocity = Vector3.zero
                end)
            end
            local function returnCFrame()
                if fopt.ret == "Lobby" then
                    local cf = lobbyCFrame and lobbyCFrame()
                    if cf then return cf end
                    for _, name in ipairs({ "Lobby", "LobbyMap", "Voting", "Waiting" }) do
                        local inst = workspace:FindFirstChild(name)
                        local p = inst and inst:FindFirstChildWhichIsA("BasePart", true)
                        if p then return p.CFrame + Vector3.new(0, 4, 0) end
                    end
                    return lastMapCF
                end
                local map = findMapModel and findMapModel()
                local cf = (mapCFrame and mapCFrame(map)) or lastMapCF
                if not cf then return nil end
                if fopt.ret == "Above Map" then
                    return cf + Vector3.new(0, 40, 0)
                end
                return cf
            end
            local function tweenTo(cf)
                local r = localRoot()
                if not r or not cf then return end
                if farmTw then pcall(function() farmTw:Cancel() end); farmTw = nil end
                local dist = (r.Position - cf.Position).Magnitude
                if dist <= 2.5 then
                    freezeRoot(r, true)
                    r.CFrame = cf
                    freezeRoot(r, false)
                    return
                end
                freezeRoot(r, true)
                local spd = 8 + fopt.spd * 0.55
                local dur = math.clamp(dist / math.max(spd, 10), 0.08, 1.35)
                farmTw = TweenService:Create(r, TweenInfo.new(dur, Enum.EasingStyle.Linear), { CFrame = cf })
                farmTw:Play()
                local t0 = os.clock()
                while farming and os.clock() - t0 < dur + 0.02 do
                    if not farmTw or farmTw.PlaybackState ~= Enum.PlaybackState.Playing then break end
                    task.wait()
                end
                if farmTw then pcall(function() farmTw:Cancel() end); farmTw = nil end
                if r.Parent then r.CFrame = cf end
                freezeRoot(r, false)
            end
            local function setNoclip(on)
                if noclipConn then noclipConn:Disconnect(); noclipConn = nil end
                local char = LocalPlayer.Character
                if not on then
                    if char then
                        for _, p in ipairs(char:GetChildren()) do
                            if p:IsA("BasePart") then p.CanCollide = true end
                        end
                    end
                    return
                end
                noclipConn = RunService.Stepped:Connect(function()
                    if not farming then return end
                    local c = LocalPlayer.Character
                    if not c then return end
                    for _, p in ipairs(c:GetChildren()) do
                        if p:IsA("BasePart") then p.CanCollide = false end
                    end
                end)
            end
            local function magnetCoins()
                local char = LocalPlayer.Character
                local root = localRoot()
                if not char or not root then return 0 end
                freezeRoot(root, false)
                local parts = getCoinParts()
                for n = 1, #parts do
                    local part = parts[n]
                    if part and part.Parent then
                        touch(root, part)
                        for _, bp in ipairs(char:GetChildren()) do
                            if bp:IsA("BasePart") then touch(bp, part) end
                        end
                    end
                end
                return #parts
            end
            local function collectAura()
                local root = localRoot()
                if not root then return end
                local pos = root.Position
                local parts = getCoinParts()
                for n = 1, #parts do
                    local part = parts[n]
                    if part and part.Parent and (pos - part.Position).Magnitude <= auraRadius then
                        touch(root, part)
                    end
                end
            end
            local function hasTool(name)
                local char, bp = LocalPlayer.Character, LocalPlayer:FindFirstChild("Backpack")
                return (char and char:FindFirstChild(name)) or (bp and bp:FindFirstChild(name))
            end
            local function doKillAll()
                local char = LocalPlayer.Character
                local knife = char and char:FindFirstChild("Knife") or (LocalPlayer:FindFirstChild("Backpack") and LocalPlayer.Backpack:FindFirstChild("Knife"))
                local ht = knife and knife:FindFirstChild("Events") and knife.Events:FindFirstChild("HandleTouched")
                if not ht then return end
                for _, plr in ipairs(Players:GetPlayers()) do
                    if plr ~= LocalPlayer and plr.Character then
                        local tgt = plr.Character:FindFirstChild("UpperTorso") or plr.Character:FindFirstChild("HumanoidRootPart")
                        if tgt then pcall(function() ht:FireServer(tgt) end) end
                    end
                end
            end
            local function doShootMurd()
                task.spawn(function()
                    local gun = hasTool("Gun")
                    local murd = findByKnife and findByKnife()
                    if not gun or not murd then return end
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                    if hum and gun.Parent ~= LocalPlayer.Character then pcall(function() hum:EquipTool(gun) end) end
                    task.wait(0.2)
                    pcall(function()
                        local vu = game:GetService("VirtualUser")
                        local cam = workspace.CurrentCamera
                        local center = Vector2.new(cam.ViewportSize.X / 2, cam.ViewportSize.Y / 2)
                        vu:Button1Down(center, cam.CFrame)
                        task.wait(0.1)
                        vu:Button1Up(center, cam.CFrame)
                    end)
                end)
            end
            local function maybeRoleReset()
                local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if not hum then return end
                if fopt.rstM and hasTool("Knife") then hum.Health = 0 end
                if fopt.rstS and hasTool("Gun") then hum.Health = 0 end
            end
            local function murdTooClose()
                if not fopt.avoid then return false end
                local murd = findByKnife and findByKnife()
                local r = localRoot()
                local hrp = murd and murd.Character and murd.Character:FindFirstChild("HumanoidRootPart")
                if not r or not hrp then return false end
                return (r.Position - hrp.Position).Magnitude < 38
            end
            local function onBagFull()
                bagIsFull = true
                if not farming then return end
                notify("40 монет — bag full", 3)
                if killAllOn then task.spawn(doKillAll) end
                if shootMurdOn then doShootMurd() end
                if resetFull then
                    local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                    if hum then hum.Health = 0 end
                end
            end
            pcall(function()
                local gp = ReplicatedStorage:FindFirstChild("Remotes")
                gp = gp and gp:FindFirstChild("Gameplay")
                local ev = gp and gp:FindFirstChild("CoinCollected")
                if ev and ev.OnClientEvent then
                    ev.OnClientEvent:Connect(function(_, current, max)
                        current, max = tonumber(current), tonumber(max)
                        if current and max and current >= max then onBagFull() end
                    end)
                end
                local endEv = gp and gp:FindFirstChild("RoundEndFade")
                if endEv and endEv.OnClientEvent then
                    endEv.OnClientEvent:Connect(function() bagIsFull = false end)
                end
                local startEv = gp and gp:FindFirstChild("RoundStart")
                if startEv and startEv.OnClientEvent then
                    startEv.OnClientEvent:Connect(function() bagIsFull = false end)
                end
            end)
            pcall(function()
                LocalPlayer.Idled:Connect(function()
                    local vu = game:GetService("VirtualUser")
                    vu:CaptureController()
                    vu:ClickButton2(Vector2.new())
                end)
            end)
            local function farmBtn(parent, label, fn)
                local b = New("TextButton", { Parent = parent, Size = UDim2.new(1, 0, 0, 46), BackgroundColor3 = C.btn,
                    BackgroundTransparency = .32, BorderSizePixel = 0, Text = label, TextColor3 = C.text, TextSize = 15,
                    Font = Enum.Font.GothamMedium, AutoButtonColor = false })
                corner(b, 11); local edge = stroke(b, C.border, .24); edge.Thickness = 1.35
                b.MouseEnter:Connect(function() TweenService:Create(b, TweenInfo.new(.16), { BackgroundColor3 = Color3.fromRGB(22,24,29), BackgroundTransparency = .18 }):Play() end)
                b.MouseLeave:Connect(function() TweenService:Create(b, TweenInfo.new(.18), { BackgroundColor3 = C.btn, BackgroundTransparency = .32 }):Play() end)
                b.MouseButton1Click:Connect(fn)
                b.Activated:Connect(fn)
                return b
            end
            local function makeFarmSlider(parent, label, minV, maxV, default, cb)
                local r = New("Frame", { Parent = parent, Size = UDim2.new(1, 0, 0, 68), BackgroundTransparency = 1 })
                text(r, label, 16, UDim2.fromOffset(0, 8))
                local value = New("TextBox", { Parent = r, Position = UDim2.new(1, -72, 0, 5), Size = UDim2.fromOffset(72, 30), BackgroundColor3 = C.surface,
                    BackgroundTransparency = .30, Text = tostring(default), TextColor3 = C.text, TextSize = 14, Font = Enum.Font.Gotham,
                    TextXAlignment = Enum.TextXAlignment.Center, ClearTextOnFocus = false })
                corner(value, 9); stroke(value, C.border, .4)
                local track = New("TextButton", { Parent = r, Position = UDim2.new(0, 0, 1, -18), Size = UDim2.new(1, 0, 0, 6),
                    BackgroundColor3 = Color3.fromRGB(7,8,11), BackgroundTransparency = .30, BorderSizePixel = 0, Text = "", AutoButtonColor = false })
                corner(track, 3)
                local trackEdge = stroke(track, C.border, .54); trackEdge.Thickness = 1
                local span = math.max(maxV - minV, 1)
                local fill = New("Frame", { Parent = track, Size = UDim2.fromScale((default - minV) / span, 1), BackgroundColor3 = C.accent, BorderSizePixel = 0 })
                corner(fill, 3)
                local knob = New("Frame", { Parent = track, AnchorPoint = Vector2.new(.5, .5), Position = UDim2.new((default - minV) / span, 0, .5, 0),
                    Size = UDim2.fromOffset(14, 14), BackgroundColor3 = Color3.fromRGB(255, 255, 255), BorderSizePixel = 0, ZIndex = 2 })
                corner(knob, 7)
                local current = default
                local function set(v)
                    current = math.clamp(math.floor((tonumber(v) or current or default) + .5), minV, maxV)
                    fill.Size = UDim2.fromScale((current - minV) / span, 1)
                    knob.Position = UDim2.new((current - minV) / span, 0, .5, 0)
                    value.Text = tostring(current)
                    cb(current)
                    farmWrite("sliders", label, current)
                end
                set(default)
                value.FocusLost:Connect(function() set(value.Text) end)
                local drag = false
                local function fromInput(i)
                    local w = track.AbsoluteSize.X
                    if w < 1 then return end
                    set(minV + span * math.clamp((i.Position.X - track.AbsolutePosition.X) / w, 0, 1))
                end
                track.InputBegan:Connect(function(i)
                    if isPrimaryPress(i) then drag = true; fromInput(i) end
                end)
                track.InputEnded:Connect(function(i)
                    if isPrimaryPress(i) then drag = false end
                end)
                UIS.InputChanged:Connect(function(i)
                    if drag and (i.UserInputType == Enum.UserInputType.Touch or i.UserInputType == Enum.UserInputType.MouseMovement) then
                        fromInput(i)
                    end
                end)
                UIS.InputEnded:Connect(function(i)
                    if isPrimaryPress(i) then drag = false end
                end)
            end
            local function goHome()
                local r = localRoot()
                local cf = returnCFrame()
                if not r or not cf then return false end
                freezeRoot(r, false)
                r.CFrame = cf
                pcall(function()
                    r.AssemblyLinearVelocity = Vector3.zero
                    r.AssemblyAngularVelocity = Vector3.zero
                end)
                return true
            end
            local function stopFarmHold()
                local hum = LocalPlayer.Character and LocalPlayer.Character:FindFirstChildOfClass("Humanoid")
                if hum then
                    hum.PlatformStand = false
                    hum.AutoRotate = true
                    pcall(function()
                        hum.WalkSpeed = 16
                        hum.JumpPower = 50
                        hum.JumpHeight = 7.2
                    end)
                end
                freezeRoot(localRoot(), false)
                pcall(function() workspace.FallenPartsDestroyHeight = origDestroyH end)
            end
            pcall(function()
                LocalPlayer.CharacterAdded:Connect(function(char)
                    local hrp = char:WaitForChild("HumanoidRootPart", 5)
                    task.wait(0.25)
                    freezeRoot(hrp, false)
                    local hum = char:FindFirstChildOfClass("Humanoid")
                    if hum then hum.PlatformStand = false; hum.AutoRotate = true end
                    if farming then
                        holdReturnUntil = os.clock() + 0.9
                        goHome()
                        setStatus("Return To " .. fopt.ret)
                    end
                end)
            end)

            local holder = panel("Autofarm", "Tween Speed / Delay как Overdrive", "farm", farmCol or col)
            statusLbl = New("TextLabel", { Parent = holder, Size = UDim2.new(1, 0, 0, 22), BackgroundTransparency = 1,
                Text = "Idle", TextColor3 = C.dim, TextSize = 13, Font = Enum.Font.Gotham, TextXAlignment = Enum.TextXAlignment.Left })
            makeToggle(holder, "Auto Farm", function(on)
                farming = on
                if not on then
                    if farmTw then pcall(function() farmTw:Cancel() end); farmTw = nil end
                    setNoclip(false)
                    stopFarmHold()
                    goHome()
                    setStatus("Return To " .. fopt.ret)
                    notify("Autofarm OFF → " .. fopt.ret, 2)
                    return
                end
                notify("Autofarm ON · " .. fopt.method, 2)
                pcall(function() workspace.FallenPartsDestroyHeight = -50000 end)
                setNoclip(true)
                task.spawn(function()
                    while farming do
                        local char = LocalPlayer.Character
                        local r = localRoot()
                        local hum = char and char:FindFirstChildOfClass("Humanoid")
                        if not r or not hum or hum.Health <= 0 then
                            freezeRoot(r, false)
                            setStatus("Wait respawn...")
                            task.wait(0.4)
                            continue
                        end
                        if os.clock() < holdReturnUntil then
                            task.wait(0.08)
                            continue
                        end
                        if bagIsFull then
                            setStatus("Bag full (40)")
                            maybeRoleReset()
                            task.wait(1)
                            continue
                        end
                        maybeRoleReset()
                        local parts = getCoinParts()
                        if #parts > 0 then
                            lastMapCF = CFrame.new(parts[1].Position + Vector3.new(0, 5, 0))
                        end
                        if #parts == 0 then
                            lastCoin = nil
                            goHome()
                            setStatus("Return To " .. fopt.ret)
                            task.wait(0.45)
                            continue
                        end
                        if murdTooClose() then
                            setStatus("Avoid Murderer")
                            task.wait(0.4)
                            continue
                        end
                        if fopt.method == "Lay" then
                            hum.PlatformStand = true
                            hum.AutoRotate = false
                        else
                            hum.PlatformStand = false
                            hum.AutoRotate = true
                        end
                        local part, bestD = nil, 1e9
                        local fallback, fallD = nil, 1e9
                        for n = 1, #parts do
                            local p = parts[n]
                            if p and p.Parent then
                                local d = (r.Position - p.Position).Magnitude
                                if d < fallD then fallD, fallback = d, p end
                                if p ~= lastCoin and d < bestD then bestD, part = d, p end
                            end
                        end
                        part = part or fallback
                        if not part then
                            task.wait(0.15)
                            continue
                        end
                        setStatus(fopt.method .. " · spd " .. tostring(fopt.spd) .. "% · coins " .. tostring(#parts))
                        tweenTo(poseAt(part))
                        local root = localRoot()
                        if root and part and part.Parent then
                            freezeRoot(root, false)
                            touch(root, part)
                            magnetCoins()
                        end
                        lastCoin = part
                        local waitD = fopt.dly * 0.01
                        if waitD < 0.01 then waitD = 0.01 end
                        task.wait(waitD)
                    end
                    setNoclip(false)
                    stopFarmHold()
                    goHome()
                    setStatus("Idle")
                end)
            end)
            makeFarmSlider(holder, "Tween Speed (%)", 1, 100, fopt.spd, function(v) fopt.spd = v end)
            makeFarmSlider(holder, "Tween Delay (%)", 0, 100, fopt.dly, function(v) fopt.dly = v end)
            local methodBtn = farmBtn(holder, "Method: " .. fopt.method, function() end)
            local methods, mi = { "Standard", "Lay" }, (fopt.method == "Lay" and 2 or 1)
            methodBtn.MouseButton1Click:Connect(function()
                mi = mi % #methods + 1
                fopt.method = methods[mi]
                methodBtn.Text = "Method: " .. fopt.method
                farmWrite("dropdowns", "Method", fopt.method)
                notify("Farm method: " .. fopt.method, 2)
            end)
            local retBtn = farmBtn(holder, "Return To: " .. fopt.ret, function() end)
            local rets = { "Map", "Above Map", "Lobby" }
            local reti = 1
